import asyncio
import time

STEP_TIMEOUT_SECONDS = 30
MAX_ATTEMPTS = 3

class Orchestrator:
    def __init__(self, agent_clients):
        # agent_clients maps an agent name to an already connected MCP client
        self.agent_clients = agent_clients
        self.ledger = {}

    async def run_plan(self, plan):
        for step in plan.steps:
            await self.run_step(step)

    async def run_step(self, step):
        self.ledger.setdefault(step.id, {"attempts": 0, "status": "pending"})
        entry = self.ledger[step.id]

        while entry["attempts"] < MAX_ATTEMPTS:
            entry["attempts"] += 1
            entry["status"] = "running"
            entry["started_at"] = time.time()

            client = self.agent_clients[step.agent]
            try:
                result = await asyncio.wait_for(
                    client.call_tool(step.tool_name, step.arguments),
                    timeout=STEP_TIMEOUT_SECONDS
                )
                entry["status"] = "done"
                entry["result"] = result
                return result
            except asyncio.TimeoutError:
                entry["status"] = "stuck"
                self.log_stuck(step, reason="timeout")
            except Exception as exc:
                entry["status"] = "stuck"
                self.log_stuck(step, reason=str(exc))

        entry["status"] = "escalated"
        return self.escalate(step)

    def log_stuck(self, step, reason):
        print(f"step {step.id} on agent {step.agent} stuck, reason: {reason}")

    def escalate(self, step):
        print(f"step {step.id} exceeded max attempts, escalating")
        return {"status": "needs_human_review", "step_id": step.id}

async def call_agent_safely(client, tool_name, arguments):
    try:
        return await asyncio.wait_for(
            client.call_tool(tool_name, arguments),
            timeout=STEP_TIMEOUT_SECONDS
        )
    except Exception as exc:
        # never let one agent's failure take down the orchestrator loop
        return {"error": str(exc)}
